#!/usr/bin/env python3
"""Replace old POINT and test overview with six clean topics, preserving cards."""
import json,re,subprocess
from pathlib import Path
p=Path("index.html")
s=p.read_text(encoding="utf-8")
assert s.count("const POINT_TOPICS=[")==1
start=s.index("const POINT_TOPICS=[")
end=s.index("\n];\n\n\nfunction renderPoints()",start)+len("\n];")
old=s[start:end]
assert old.count("id:")==7, ("Unexpected old sections",old.count("id:"))
assert "テスト概要" in old
basepos=s.index("const BASE=")+len("const BASE=")
base,_=json.JSONDecoder().raw_decode(s[basepos:])
a=s.index("BASE.push(")+len("BASE.push(")
b=s.index("\n);",a)
extra=json.loads("["+s[a:b].strip().strip(",")+"]")
assert (len(base),len(extra))==(190,83),(len(base),len(extra))
cards_before=json.dumps(base+extra,ensure_ascii=False,separators=(",",":"))
replacement="const POINT_TOPICS=[{\"id\":\"parts-of-speech\",\"title\":\"① 品詞の見分け方\",\"subtitle\":\"空欄の前後を見る・名詞と動詞の同形語\",\"html\":\"<div class=\\\"pointNote\\\"><b>3秒ルール：空欄の前後を見る！</b><br>何を修飾するか・文のどこに入るかで判断。</div><div class=\\\"pointSection\\\"><h3>品詞の基本</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">名詞</div><div class=\\\"value\\\">主語・目的語・補語になる。<br>例：the <b>report</b></div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">形容詞</div><div class=\\\"value\\\"><b>名詞</b>を修飾する。<br>例：a <b>reliable</b> employee</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">副詞</div><div class=\\\"value\\\"><b>動詞・形容詞・副詞・文全体</b>を修飾する。<br>例：work <b>efficiently</b></div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">前置詞</div><div class=\\\"value\\\">後ろに<b>名詞・動名詞</b>。<br>例：despite the delay</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">接続詞</div><div class=\\\"value\\\">後ろに<b>S＋V</b>の節。<br>例：because it rained</div></div></div></div><div class=\\\"pointSection\\\"><h3>同じ形で名詞にも動詞にもなる語</h3><div class=\\\"sameFormTable\\\"><div class=\\\"sameFormHead\\\"><span>単語</span><span>名詞</span><span>動詞</span></div><div class=\\\"sameFormRow\\\"><span class=\\\"sameFormWord\\\">increase</span><span class=\\\"sameFormMeaning\\\">増加</span><span class=\\\"sameFormMeaning\\\">増える・増やす</span></div><div class=\\\"sameFormRow\\\"><span class=\\\"sameFormWord\\\">decrease</span><span class=\\\"sameFormMeaning\\\">減少</span><span class=\\\"sameFormMeaning\\\">減る・減らす</span></div><div class=\\\"sameFormRow\\\"><span class=\\\"sameFormWord\\\">estimate</span><span class=\\\"sameFormMeaning\\\">見積もり</span><span class=\\\"sameFormMeaning\\\">見積もる</span></div><div class=\\\"sameFormRow\\\"><span class=\\\"sameFormWord\\\">forecast</span><span class=\\\"sameFormMeaning\\\">予測・予報</span><span class=\\\"sameFormMeaning\\\">予測する</span></div><div class=\\\"sameFormRow\\\"><span class=\\\"sameFormWord\\\">recruit</span><span class=\\\"sameFormMeaning\\\">新人</span><span class=\\\"sameFormMeaning\\\">採用する・募集する</span></div><div class=\\\"sameFormRow\\\"><span class=\\\"sameFormWord\\\">respect</span><span class=\\\"sameFormMeaning\\\">尊敬</span><span class=\\\"sameFormMeaning\\\">尊敬する</span></div><div class=\\\"sameFormRow\\\"><span class=\\\"sameFormWord\\\">order</span><span class=\\\"sameFormMeaning\\\">順序・注文</span><span class=\\\"sameFormMeaning\\\">命じる・注文する</span></div></div><div class=\\\"pointNote\\\">同じスペルでも<b>文中の位置</b>から名詞か動詞か判断！</div></div>\"},{\"id\":\"prepositions-conjunctions\",\"title\":\"② 前置詞・接続詞・接続副詞\",\"subtitle\":\"名詞？ S＋V？ 文と文の意味？\",\"html\":\"<div class=\\\"pointNote\\\"><b>3秒ルール</b>：前置詞→名詞 ／ 接続詞→S＋V<br>接続副詞は2つの独立した文を単独で直接つなげない。</div><div class=\\\"pointSection\\\"><h3>前置詞＋名詞</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">rather than</div><div class=\\\"value\\\">～よりむしろ</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">aside from</div><div class=\\\"value\\\">～を除いて／～に加えて</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">despite / in spite of</div><div class=\\\"value\\\">～にもかかわらず</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">notwithstanding</div><div class=\\\"value\\\">～にもかかわらず（前置詞としても使用）</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">in the event of</div><div class=\\\"value\\\">～の場合</div></div></div><div class=\\\"pointNote\\\">例：<b>Despite the rain</b>, the event continued.</div></div><div class=\\\"pointSection\\\"><h3>接続詞＋S＋V</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">because / since</div><div class=\\\"value\\\">～なので</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">when / while</div><div class=\\\"value\\\">～するとき／～の間</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">as</div><div class=\\\"value\\\">～につれて／～なので／～するとき</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">as long as</div><div class=\\\"value\\\">～する限り／～という条件で</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">in the event that</div><div class=\\\"value\\\">～の場合</div></div></div><div class=\\\"pointNote\\\">例：<b>Because it rained</b>, the event was postponed.</div></div><div class=\\\"pointSection\\\"><h3>接続副詞・結果を示す副詞</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">therefore / thus</div><div class=\\\"value\\\">したがって</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">consequently</div><div class=\\\"value\\\">その結果</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">nevertheless</div><div class=\\\"value\\\">それでもなお</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">meanwhile</div><div class=\\\"value\\\">その間</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">namely</div><div class=\\\"value\\\">具体的には</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">thereby</div><div class=\\\"value\\\">それによって（副詞）</div></div></div><div class=\\\"pointNote\\\">例：It was raining. <b>Therefore,</b> we stayed inside.</div></div>\"},{\"id\":\"verb-patterns\",\"title\":\"③ 動詞の後ろの形・使役\",\"subtitle\":\"make / have / let / help と be＋ing\",\"html\":\"<div class=\\\"pointNote\\\"><b>3秒ルール</b>：「人＋原形」「物＋過去分詞」を区別！</div><div class=\\\"pointSection\\\"><h3>使役動詞の形</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">make＋人＋原形</div><div class=\\\"value\\\">人に～させる</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">let＋人＋原形</div><div class=\\\"value\\\">人に～することを許す</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">have＋人＋原形</div><div class=\\\"value\\\">人に～してもらう／～させる</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">help＋人＋(to) 原形</div><div class=\\\"value\\\">人が～するのを助ける</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">have＋物＋過去分詞</div><div class=\\\"value\\\">物を～してもらう（文脈により、～される）</div></div></div></div><div class=\\\"pointSection\\\"><h3>例文で比較</h3><div class=\\\"pointCols\\\"><div class=\\\"pointMini\\\"><h4>人＋原形</h4><p><b>I had a technician check the machine.</b><br>技術者に機械を点検してもらった。</p></div><div class=\\\"pointMini\\\"><h4>物＋過去分詞</h4><p><b>I had the machine repaired.</b><br>機械を修理してもらった。</p></div></div></div><div class=\\\"pointSection\\\"><h3>be＋動詞-ing</h3><p><b>進行中</b>だけでなく、<b>決まっている未来の予定</b>にも使える。</p><div class=\\\"pointNote\\\">We <b>are meeting</b> the client tomorrow.（明日その顧客に会う予定）</div></div>\"},{\"id\":\"omission-inversion\",\"title\":\"④ 省略・倒置・that節\",\"subtitle\":\"接続詞の省略・nor・要求/提案・時制\",\"html\":\"<div class=\\\"pointNote\\\"><b>3秒ルール</b>：省略はS＋be ／ norの後は倒置 ／ 提案・要求のthat節は原形に注目。</div><div class=\\\"pointSection\\\"><h3>接続詞の後の省略</h3><p>主節と従属節の主語が同じで、従属節が<b>主語＋be動詞</b>なら、省略できることがある。</p><div class=\\\"pointNote\\\">When <b>(it is)</b> completed, the form will be sent by email.</div></div><div class=\\\"pointSection\\\"><h3>nor の倒置</h3><p>否定に続ける場合、<b>nor＋助動詞＋主語</b>。</p><div class=\\\"pointNote\\\">I don't drink, <b>nor do I</b> smoke.</div></div><div class=\\\"pointSection\\\"><h3>提案・要求のthat節</h3><p>suggest / propose / require / demand などのthat節では<b>動詞の原形</b>を使う形がある。</p><div class=\\\"pointNote\\\">We suggested that he <b>attend</b> the meeting.</div></div><div class=\\\"pointSection\\\"><h3>時・条件の副詞節</h3><p>未来のことでもwhen / ifの副詞節は通常<b>現在形</b>。</p><div class=\\\"pointNote\\\">If it <b>rains</b> tomorrow, we will postpone the event.</div></div>\"},{\"id\":\"pronouns-countability\",\"title\":\"⑤ 代名詞・可算・不可算\",\"subtitle\":\"単数・複数 / few と little\",\"html\":\"<div class=\\\"pointNote\\\"><b>3秒ルール</b>：数えられる？ 単数？ 複数？</div><div class=\\\"pointSection\\\"><h3>名詞の前に置く語</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">可算単数</div><div class=\\\"value\\\">each / every / either / neither / another</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">可算複数</div><div class=\\\"value\\\">many / few / a few / several / both</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">不可算</div><div class=\\\"value\\\">much / little / a little</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">可算・不可算どちらも</div><div class=\\\"value\\\">all / most / some / any / enough</div></div></div></div><div class=\\\"pointSection\\\"><h3>few / little の比較</h3><div class=\\\"pointCols\\\"><div class=\\\"pointMini\\\"><h4>ほとんどない</h4><p><b>few</b>＋可算複数<br><b>little</b>＋不可算</p></div><div class=\\\"pointMini\\\"><h4>少しある</h4><p><b>a few</b>＋可算複数<br><b>a little</b>＋不可算</p></div></div></div><div class=\\\"pointSection\\\"><h3>代名詞の単数・複数扱い</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">単数扱い</div><div class=\\\"value\\\">someone / anybody / everyone / nobody / something / anything / everything / nothing / each / either / neither / another</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">複数扱い</div><div class=\\\"value\\\">both / many / few / several / others / the others（複数）</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">両方あり</div><div class=\\\"value\\\">all / most / some / any / none（指す内容によって変化）</div></div></div><div class=\\\"pointNote\\\"><b>the other</b> は単数・複数どちらもOK：the other book / the other books</div></div>\"},{\"id\":\"confusing-sets\",\"title\":\"⑥ 間違えやすい文法セット\",\"subtitle\":\"until / by・自動詞 / 他動詞・as\",\"html\":\"<div class=\\\"pointNote\\\"><b>3秒ルール</b>：似たものは『違い』をペアで覚える！</div><div class=\\\"pointSection\\\"><h3>until と by</h3><div class=\\\"pointCols\\\"><div class=\\\"pointMini\\\"><h4>until＝継続の終点</h4><p>～までずっと<br><b>Stay until 5.</b></p></div><div class=\\\"pointMini\\\"><h4>by＝期限</h4><p>遅くとも～までに<br><b>Finish by 5.</b></p></div></div></div><div class=\\\"pointSection\\\"><h3>自動詞と他動詞</h3><div class=\\\"pointCols\\\"><div class=\\\"pointMini\\\"><h4>自動詞</h4><p>目的語を直接取らない。<br><b>go to</b> the office<br><b>arrive at</b> the station</p></div><div class=\\\"pointMini\\\"><h4>他動詞</h4><p>目的語を直接取る。<br><b>discuss</b> the plan<br><b>attend</b> the meeting</p></div></div><div class=\\\"pointNote\\\">「～を議論する」なら × discuss about the plan → ○ discuss the plan</div></div><div class=\\\"pointSection\\\"><h3>as と as long as</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">as</div><div class=\\\"value\\\">～につれて／～なので／～するとき（文脈判断）</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">as long as</div><div class=\\\"value\\\">～する限り／～という条件で</div></div></div><div class=\\\"pointNote\\\"><b>As</b> sales grow, we will hire more staff.<br><b>As long as</b> you agree, we can proceed.</div></div><div class=\\\"pointSection\\\"><h3>未来：be＋ing と will</h3><div class=\\\"pointRows\\\"><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">be＋ing</div><div class=\\\"value\\\">すでに決まっている予定：We are leaving tomorrow.</div></div><div class=\\\"pointRow2\\\"><div class=\\\"label\\\">will＋原形</div><div class=\\\"value\\\">意思・予測・その場の判断：I will call you.</div></div></div></div>\"}];"
s2=s[:start]+replacement+s[end:]
assert "テスト概要" not in s2 and "test-overview" not in s2
assert s2[:start]==s[:start] and s2[start+len(replacement):]==s[end:]
bp=s2.index("const BASE=")+len("const BASE=")
base2,_=json.JSONDecoder().raw_decode(s2[bp:])
a2=s2.index("BASE.push(")+len("BASE.push(")
b2=s2.index("\n);",a2)
extra2=json.loads("["+s2[a2:b2].strip().strip(",")+"]")
assert json.dumps(base2+extra2,ensure_ascii=False,separators=(",",":"))==cards_before
assert "preserveMergedCardProgress" in s2
assert all(x["id"] in {c["id"] for c in base2+extra2} for x in base2 if x["front"] in ["call off","mail"])
assert len([x for x in base2+extra2 if x["front"] in ["call off","mail"]])==2
assert s2.rstrip().endswith("</html>")
scripts=re.findall(r"<script(?:\\s[^>]*)?>(.*?)</script>",s2,re.S|re.I)
assert len(scripts)==1
js=Path("/tmp/point_rework.js")
js.write_text(scripts[0],encoding="utf-8")
ck=subprocess.run(["node","--check",str(js)],capture_output=True,text=True)
assert ck.returncode==0,ck.stderr
p.write_text(s2,encoding="utf-8")
print("SUCCESS: new POINT themes = 6, removed test overview.")
print("Validated 273 cards with images and progress code unchanged.")
print("POINT titles:","① 品詞の見分け方 | ② 前置詞・接続詞・接続副詞 | ③ 動詞の後ろの形・使役 | ④ 省略・倒置・that節 | ⑤ 代名詞・可算・不可算 | ⑥ 間違えやすい文法セット")
print("JavaScript syntax validation passed.")
